Step.Code:
/* Load any uncompiled macros specific to this analysis            */
%afi_caf_loadmacros(/Products/SAS Analytics For IoT/CustomAnalyses/macros);

/* PREPROCESS to prepare for analysis work */
%afi_caf_preprocess(?g_cas, ?analysisID);

libname Public cas caslib=Public;
cas  casuser  sessopts=(caslib=casuser timeout=1800 locale="en_US");

libname casuser cas caslib=casuser;

libname x postgres user=postgres pwd=<REDACTED> database=postgres 
        server="postgres-0.postgres.postgres.svc.cluster.local" 
        schema=public;

option mprint; 
%global st_dt_all end_dt_all;
%macro dataIngest; 

	%put &g_p_inTags; 

	%let varlist_new =%sysfunc(tranwrd(%quote(&g_p_inTags), %str(,), %str(",")));

	%put &varlist_new; 

	%let st_dt=%substr(&g_p_StrtDt_T,9,2);
	%let st_mn=%substr(&g_p_StrtDt_T,4,4);
	%let st_yr=%substr(&g_p_StrtDt_T,12,4);
	%let st_tm=%substr(&g_p_StrtDt_T,17,8);
	%let st_dt_all=&st_dt.&st_mn.&st_yr.:&st_tm;
	%put &st_dt. &st_mn. &st_yr. &st_tm. &st_dt_all. ;

	%let end_dt=%substr(&g_p_EndDt_T,9,2);
	%let end_mn=%substr(&g_p_EndDt_T,4,4);
	%let end_yr=%substr(&g_p_EndDt_T,12,4);
	%let end_tm=%substr(&g_p_EndDt_T,17,8);
	%let end_dt_all=&end_dt.&end_mn.&end_yr.:&end_tm;
	%put &end_dt. &end_mn. &end_yr. &end_tm. &end_dt_all. ;

	data _null_;
		epoch_dttm_Strt = "&st_dt_all"dt  - 315619200;
		epoch_dttm_End  = "&end_dt_all"dt - 315619200;
			call symputx("strtDt",epoch_dttm_Strt);
			call symputx("endDt",epoch_dttm_End);
	run; 

	%put &strtDt. &endDt. ; 

	proc sql; 
		create table dataSubset  as
		select  * 
		from x.HISTORICALDATA_AHU_PITAGS
		where facilitycode="&g_p_facility." and pitag in ("&varlist_new.","&g_p_targetnm") and (epochdttm gt &strtDt. and epochdttm lt &endDt.); 
	quit; /* to add: date filters */

	proc sql; 
		create table pitag_join as
		select t1.*, t2.assetDesc, t2.assetID, t2.SASAttributeID, t2.attributeLabel
		from dataSubset as t1 left join public.hvac_piMap as t2 on t1.pitag=t2.pitag; 
	quit; 


	data pitag_join; 
		format datetime datetime_rnd datetime20.; 
		set pitag_join; 
		datetime = dhms(mdy(1,1,1970),0,0, epochdttm);
		datetime_rnd=round(datetime,60); 
	run; 

	proc sort data=pitag_join nodupkey; 
		by datetime_rnd SASAttributeID;
	run; 

	proc transpose data=pitag_join out=casuser.abtTrain(drop=_name_ _label_ rename=(datetime_rnd=msr_dttm)); 
		by datetime_rnd assetID facilitycode; 
		id SASAttributeID;
		idlabel attributeLabel;
		var value; 
	run; 

	data casuser.abtTrain; 
		set casuser.abtTrain; 
		if ahu_act_sply_air_sp < 200 then runConditionC ="1"; 
		else runConditionC="0";
	run; 

	%macro smoothTarget; /* WIP */

		data _null_;
			set public.hvac_piMap  ; 
			call symputx("smoothVar",SASAttributeID);
			where pitag in ("&g_p_targetnm");
		run; 

	%put &strtDt. &endDt. ; 
		 proc expand data=casuser.abtTrain out=casuser.abtTrain; 
 			id datetime; 
 	 		convert &g_p_variable. = &smoothVar._MA / transout=(movave &g_p_mwindow.); 
 	run; 

	%mend; 

	data assetMetadata;
		set public.hvac_piMap  ; 
		where pitag in ("&varlist_new.","&g_p_targetnm");
	run; 

	data selectDtRng;
		format Start_Dt_rng End_Dt_rng $100.;
		Start_Dt_rng = "&st_dt_all.";
		End_Dt_rng = "&end_dt_all.";
	run; 

%mend; 

%dataIngest;

	proc sql; 
		select SASAttributeID
		into :targetTag
		from assetMetadata
		where PiTag="&g_p_targetnm";
	quit;

	proc sql; 
		select SASAttributeID
		into :inputTags separated by ' '
		from assetMetadata
		where PiTag <> "&g_p_targetnm";
	quit;

%put &inputTags.; 

%thick(indata=casuser.abtTrain, target=&targetTag. ,invars=&inputTags. , dt=msr_dttm ) ; 

%put &inputTags.; 


data casuser.thickout (rename=(dt=msr_dttm)); 
	set casuser.thickout; 
		if ahu_act_sply_air_sp < 200 then runConditionC ="1"; 
		else runConditionC="0";
	run; 
run; 

proc sql; 
	create table thicklong_pitag as
	select t1.*, t2.pitag
	from casuser.thicklong as t1 left join assetMetadata as t2 on t1.name=t2.SASAttributeID; 
quit; 

data casuser.thicklong_pitag (rename=(dt=msr_dttm)); 
	set thicklong_pitag;
run; 

data targetLookup;
		format key $50. label $15.;
    KEY="&g_analysis_type._abtTrain_&g_short_id.";
    LABEL='Raw Data';
    output;
    KEY="&g_analysis_type._thickout_&g_short_id.";
    LABEL='Reduced Data';
    output;
run;

/* To finish the analysis specific code, setup the info needed for */
/* the postprocess.                                                */

/* Provide any output tables to be persisted and used later.       */
/* Postprocess will promote and save the output tables in the      */
/* QASANLOUT global caslib using a standard naming convention of   */
/* <analysis_type>_tablename_<shortid>                             */
/* For example: CARS_filtered_ABC123                               */
/*              CARS_complete_ABC123                               */
%let g_num_output_tables = 6;
%let g_output_table_1 = work.assetMetadata;
%let g_output_table_2 = casuser.abtTrain;
%let g_output_table_3 = work.selectDtRng;
%let g_output_table_4 = casuser.thickout;
%let g_output_table_5 = work.targetLookup;
%let g_output_table_6 = casuser.thicklong_pitag;




/* Provide any output variable to be used later.                   */
/* Postprocess will save these variables into metadata so they can */
/* be used in the VA output or in later analysis steps             */
/* For example: filtered_count = 20                                */
%let g_num_output_vars = 3;
%let g_output_var_1 = g_p_inTags;
%let g_output_var_2 = st_dt_all;
%let g_output_var_3 = end_dt_all;

/* *************************************************************** */
/* END ANALYSIS SPECIFIC PROGRAMMING                               */
/* *************************************************************** */



/* PREPROCESS to save analysis work                                */
%afi_caf_postprocess;

/* PREPROCESS to prepare for analysis work                         */
%afi_caf_preprocess(?g_cas, ?analysisID);


CAS qasout SESSOPTS=(CASLIB=QASANLOUT) ;
libname qasout CAS sessref=qasout;
caslib _all_ assign;


/* %let target=&g_analysis_type._p_target_&g_short_id.; 
%let varnew=&g_analysis_type._fltrd_varlist_&g_short_id. ;
%put &target  &g_p_target;

%put &g_fltrd_varlist &&varnew.;*/ 

%let newVarlist= %sysfunc(tranwrd(%quote(&g_p_input.), %str(,), %str( )));

proc partition data=qasout.&g_analysis_type._modeldata_&g_short_id.  samppct=70 seed=123 partind;
   output out= qasout.partdata ;
/*   display 'SRSFreq';*/
run;

ods output VariableImportance=VariableImportance;

proc forest data = qasout.partdata;
	id assetID; 
   input &newVarlist. /level=interval; 
	target &g_p_target. /level=interval;
	partition rolevar=_PartIND_(train='0' validate='1');
	savestate rstore=qasout.saveFOREST; 
	output out=qasout.outForest copyvars=(_ALL_); 
run;  

proc assess data=qasout.outForest fitstatout=qasout.fst_Frst;
   var P_&g_p_target. ;
   target &g_p_target.  /level=interval ;
   fitstat pvar=P_&g_p_target.   ;
   by _PartInd_;
run;


data VarImp; 
  set VariableImportance; 
run; 


proc astore;
   download rstore = qasout.saveFOREST
            store = "/export/viya/homes/priya.sharma@sas.com/data/hvac/astore/saveFOREST.sasast";
run;

/* To finish the analysis specific code, setup the info needed for */
/* the postprocess.                                                */

/* Provide any output tables to be persisted and used later.       */
/* Postprocess will promote and save the output tables in the      */
/* QASANLOUT global caslib using a standard naming convention of   */
/* <analysis_type>_tablename_<shortid>                             */
/* For example: CARS_filtered_ABC123                               */
/*              CARS_complete_ABC123                               */

option mprint; 

%let g_num_output_tables = 4;

%let g_output_table_1 = qasout.fst_Frst;
%let g_output_table_2 = work.VarImp;
%let g_output_table_3 = qasout.outForest;
%let g_output_table_4 = qasout.partdata;



/* Provide any output variable to be used later.                   */
/* Postprocess will save these variables into metadata so they can */
/* be used in the VA output or in later analysis steps             */
/* For example: filtered_count = 20                                */
%let g_num_output_vars = 1;
%let g_output_var_1 = newVarlist;

/* *************************************************************** */
/* END ANALYSIS SPECIFIC PROGRAMMING                               */
/* *************************************************************** */



/* PREPROCESS to save analysis work                                */
%afi_caf_postprocess;
